// src/Component/ActivityLog.js

import React, { useEffect, useState } from "react";
import axios from "axios";

const ActivityLog = () => {
  const [logs, setLogs] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  // Fetch activity logs from backend
  useEffect(() => {
    const fetchLogs = async () => {
      try {
        const token = localStorage.getItem("token"); // JWT token
        const res = await axios.get("http://127.0.0.1:8000/api/activity-logs/", {
          headers: {
            Authorization: `Bearer ${token}`,
          },
        });
        setLogs(res.data);
      } catch (err) {
        console.error(err);
        setError("Failed to load activity logs");
      } finally {
        setLoading(false);
      }
    };

    fetchLogs();
  }, []);

  if (loading) return <p>Loading activity logs...</p>;
  if (error) return <p>{error}</p>;

  return (
    <div style={{ padding: "20px" }}>
      <h2>All User Activity Timeline</h2>
      {logs.length === 0 && <p>No activity logs found.</p>}
      <ul style={{ listStyle: "none", padding: 0 }}>
        {logs.map((log, index) => (
          <li
            key={index}
            style={{
              borderLeft: "2px solid #ccc",
              padding: "10px 20px",
              marginBottom: "10px",
              position: "relative",
            }}
          >
            <span
              style={{
                position: "absolute",
                left: "-10px",
                top: "10px",
                background: "#fff",
                borderRadius: "50%",
                border: "2px solid #007bff",
                width: "16px",
                height: "16px",
              }}
            ></span>
            <strong>{log.username}</strong> performed <em>{log.action}</em>{" "}
            on <strong>{log.model}</strong> {log.object_id ? `(#${log.object_id})` : ""}
            <br />
            <small>{new Date(log.timestamp).toLocaleString()}</small>
            {log.details && Object.keys(log.details).length > 0 && (
              <pre style={{ background: "#f9f9f9", padding: "5px", marginTop: "5px" }}>
                {JSON.stringify(log.details, null, 2)}
              </pre>
            )}
          </li>
        ))}
      </ul>
    </div>
  );
};

export default ActivityLog;
